        {
          *beta=FxEvaluateSubexpression(fx_info,channel,x,y,++p,recursion_depth,beta,
            exception);
          *beta=fabs(floor((*beta)+0.5));
          if (*beta == 0.0)
            {
              (void) ThrowMagickException(exception,GetMagickModule(),
                OptionError,"DivideByZero","`%s'",expression);
              FxResult(0.0);
