                segment.x2=StringToDouble(primitive_token,&next_token);
                if (primitive_token == next_token)
                  ThrowPointExpectedException(primitive_token,exception);
                GetNextToken(q,&q,extent,primitive_token);
                if (*primitive_token == ',')
                  GetNextToken(q,&q,extent,primitive_token);
                segment.y2=StringToDouble(primitive_token,&next_token);
                if (primitive_token == next_token)
                  ThrowPointExpectedException(primitive_token,exception);
                if (LocaleCompare(type,"radial") == 0)
