                for (p=q; *q != '\0'; )
                {
                  GetNextToken(q,&q,extent,primitive_token);
                  if (LocaleCompare(primitive_token,"pop") != 0)
                    continue;
                  GetNextToken(q,(const char **) NULL,extent,primitive_token);
                  if (LocaleCompare(primitive_token,"pattern") != 0)
                    continue;
                  break;
                }
                if ((size_t) (q-p-4+1) > 0)
                  {
                    (void) CopyMagickString(primitive_token,p,(size_t) (q-p-4+1));
                    (void) FormatLocaleString(key,MagickPathExtent,"%s",name);
                    (void) SetImageArtifact(image,key,primitive_token);
                    (void) FormatLocaleString(key,MagickPathExtent,
                      "%s-geometry",name);
                    (void) FormatLocaleString(geometry,MagickPathExtent,
                      "%.20gx%.20g%+.20g%+.20g",(double)pattern_bounds.width,
                      (double)pattern_bounds.height,(double)pattern_bounds.x,
                      (double)pattern_bounds.y);
                    (void) SetImageArtifact(image,key,geometry);
                  }
                GetNextToken(q,&q,extent,primitive_token);
                break;
              }
            if (LocaleCompare("graphic-context",primitive_token) == 0)
              {
                n++;
                graphic_context=(DrawInfo **) ResizeQuantumMemory(
                  graphic_context,(size_t) (n+1),sizeof(*graphic_context));
                if (graphic_context == (DrawInfo **) NULL)
                  {
                    (void) ThrowMagickException(exception,GetMagickModule(),
                      ResourceLimitError,"MemoryAllocationFailed","`%s'",
                      image->filename);
                    break;
                  }
                graphic_context[n]=CloneDrawInfo((ImageInfo *) NULL,
                  graphic_context[n-1]);
                break;
              }
            if (LocaleCompare("defs",primitive_token) == 0)
              {
                defsDepth++;
                graphic_context[n]->render=defsDepth > 0 ? MagickFalse :
                  MagickTrue;
                break;
              }
            status=MagickFalse;
            break;
          }
        status=MagickFalse;
        break;
      }
      case 'r':
      case 'R':
      {
        if (LocaleCompare("rectangle",keyword) == 0)
          {
            primitive_type=RectanglePrimitive;
            break;
          }
        if (LocaleCompare("rotate",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            angle=StringToDouble(primitive_token,&next_token);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            affine.sx=cos(DegreesToRadians(fmod((double) angle,360.0)));
            affine.rx=sin(DegreesToRadians(fmod((double) angle,360.0)));
            affine.ry=(-sin(DegreesToRadians(fmod((double) angle,360.0))));
            affine.sy=cos(DegreesToRadians(fmod((double) angle,360.0)));
            break;
          }
        if (LocaleCompare("roundRectangle",keyword) == 0)
          {
            primitive_type=RoundRectanglePrimitive;
            break;
          }
        status=MagickFalse;
        break;
      }
      case 's':
      case 'S':
      {
        if (LocaleCompare("scale",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            affine.sx=StringToDouble(primitive_token,&next_token);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            GetNextToken(q,&q,extent,primitive_token);
            if (*primitive_token == ',')
              GetNextToken(q,&q,extent,primitive_token);
            affine.sy=StringToDouble(primitive_token,&next_token);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            break;
          }
        if (LocaleCompare("skewX",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            angle=StringToDouble(primitive_token,&next_token);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            affine.ry=sin(DegreesToRadians(angle));
            break;
          }
        if (LocaleCompare("skewY",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            angle=StringToDouble(primitive_token,&next_token);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            affine.rx=(-tan(DegreesToRadians(angle)/2.0));
            break;
          }
        if (LocaleCompare("stop-color",keyword) == 0)
          {
            PixelInfo
              stop_color;

            number_stops++;
            if (number_stops == 1)
              stops=(StopInfo *) AcquireQuantumMemory(2,sizeof(*stops));
            else if (number_stops > 2)
              stops=(StopInfo *) ResizeQuantumMemory(stops,number_stops,
                sizeof(*stops));
            if (stops == (StopInfo *) NULL)
              {
                (void) ThrowMagickException(exception,GetMagickModule(),
                  ResourceLimitError,"MemoryAllocationFailed","`%s'",
                  image->filename);
                break;
              }
            GetNextToken(q,&q,extent,primitive_token);
            (void) QueryColorCompliance(primitive_token,AllCompliance,&stop_color,
              exception);
            stops[number_stops-1].color=stop_color;
            GetNextToken(q,&q,extent,primitive_token);
            stops[number_stops-1].offset=StringToDouble(primitive_token,&next_token);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            break;
          }
        if (LocaleCompare("stroke",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            (void) FormatLocaleString(pattern,MagickPathExtent,"%s",primitive_token);
            if (GetImageArtifact(image,pattern) != (const char *) NULL)
              (void) DrawPatternPath(image,draw_info,primitive_token,
                &graphic_context[n]->stroke_pattern,exception);
            else
              {
                status&=QueryColorCompliance(primitive_token,AllCompliance,
                  &graphic_context[n]->stroke,exception);
                if (graphic_context[n]->stroke_alpha != OpaqueAlpha)
                  graphic_context[n]->stroke.alpha=
                    graphic_context[n]->stroke_alpha;
              }
            break;
          }
        if (LocaleCompare("stroke-antialias",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            graphic_context[n]->stroke_antialias=
              StringToLong(primitive_token) != 0 ? MagickTrue : MagickFalse;
            break;
          }
        if (LocaleCompare("stroke-dasharray",keyword) == 0)
          {
            if (graphic_context[n]->dash_pattern != (double *) NULL)
              graphic_context[n]->dash_pattern=(double *)
                RelinquishMagickMemory(graphic_context[n]->dash_pattern);
            if (IsPoint(q) != MagickFalse)
              {
                const char
                  *r;

                r=q;
                GetNextToken(r,&r,extent,primitive_token);
                if (*primitive_token == ',')
                  GetNextToken(r,&r,extent,primitive_token);
                for (x=0; IsPoint(primitive_token) != MagickFalse; x++)
                {
                  GetNextToken(r,&r,extent,primitive_token);
                  if (*primitive_token == ',')
                    GetNextToken(r,&r,extent,primitive_token);
                }
                graphic_context[n]->dash_pattern=(double *)
                  AcquireQuantumMemory((size_t) (2UL*x+2UL),
                  sizeof(*graphic_context[n]->dash_pattern));
                if (graphic_context[n]->dash_pattern == (double *) NULL)
                  {
                    (void) ThrowMagickException(exception,GetMagickModule(),
                      ResourceLimitError,"MemoryAllocationFailed","`%s'",
                      image->filename);
                    status=MagickFalse;
                    break;
                  }
                for (j=0; j < x; j++)
                {
                  GetNextToken(q,&q,extent,primitive_token);
                  if (*primitive_token == ',')
                    GetNextToken(q,&q,extent,primitive_token);
                  graphic_context[n]->dash_pattern[j]=StringToDouble(primitive_token,
                    &next_token);
                  if (primitive_token == next_token)
                    ThrowPointExpectedException(primitive_token,exception);
                  if (graphic_context[n]->dash_pattern[j] < 0.0)
                    status=MagickFalse;
                }
                if ((x & 0x01) != 0)
                  for ( ; j < (2*x); j++)
                    graphic_context[n]->dash_pattern[j]=
                      graphic_context[n]->dash_pattern[j-x];
                graphic_context[n]->dash_pattern[j]=0.0;
                break;
              }
            GetNextToken(q,&q,extent,primitive_token);
            break;
          }
        if (LocaleCompare("stroke-dashoffset",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            graphic_context[n]->dash_offset=StringToDouble(primitive_token,
              &next_token);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            break;
          }
        if (LocaleCompare("stroke-linecap",keyword) == 0)
          {
            ssize_t
              linecap;

            GetNextToken(q,&q,extent,primitive_token);
            linecap=ParseCommandOption(MagickLineCapOptions,MagickFalse,primitive_token);
            if (linecap == -1)
              status=MagickFalse;
            else
              graphic_context[n]->linecap=(LineCap) linecap;
            break;
          }
        if (LocaleCompare("stroke-linejoin",keyword) == 0)
          {
            ssize_t
              linejoin;

            GetNextToken(q,&q,extent,primitive_token);
            linejoin=ParseCommandOption(MagickLineJoinOptions,MagickFalse,
              primitive_token);
            if (linejoin == -1)
              status=MagickFalse;
            else
              graphic_context[n]->linejoin=(LineJoin) linejoin;
            break;
          }
        if (LocaleCompare("stroke-miterlimit",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            graphic_context[n]->miterlimit=StringToUnsignedLong(primitive_token);
            break;
          }
        if (LocaleCompare("stroke-opacity",keyword) == 0)
          {
            double
              opacity;

            GetNextToken(q,&q,extent,primitive_token);
            factor=strchr(primitive_token,'%') != (char *) NULL ? 0.01 : 1.0;
            opacity=MagickMin(MagickMax(factor*
              StringToDouble(primitive_token,&next_token),0.0),1.0);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            graphic_context[n]->stroke_alpha=(MagickRealType) (QuantumRange-
              QuantumRange*(1.0-opacity));
            break;
          }
        if (LocaleCompare("stroke-width",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            graphic_context[n]->stroke_width=StringToDouble(primitive_token,&next_token);
            if (primitive_token == next_token)
              ThrowPointExpectedException(primitive_token,exception);
            break;
          }
        status=MagickFalse;
        break;
      }
      case 't':
      case 'T':
      {
        if (LocaleCompare("text",keyword) == 0)
          {
            primitive_type=TextPrimitive;
            break;
          }
        if (LocaleCompare("text-align",keyword) == 0)
          {
            ssize_t
              align;

            GetNextToken(q,&q,extent,primitive_token);
            align=ParseCommandOption(MagickAlignOptions,MagickFalse,primitive_token);
            if (align == -1)
              status=MagickFalse;
            else
              graphic_context[n]->align=(AlignType) align;
            break;
          }
        if (LocaleCompare("text-anchor",keyword) == 0)
          {
            ssize_t
              align;

            GetNextToken(q,&q,extent,primitive_token);
            align=ParseCommandOption(MagickAlignOptions,MagickFalse,primitive_token);
            if (align == -1)
              status=MagickFalse;
            else
              graphic_context[n]->align=(AlignType) align;
            break;
          }
        if (LocaleCompare("text-antialias",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            graphic_context[n]->text_antialias=StringToLong(primitive_token) != 0 ?
              MagickTrue : MagickFalse;
            break;
          }
        if (LocaleCompare("text-undercolor",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            (void) QueryColorCompliance(primitive_token,AllCompliance,
              &graphic_context[n]->undercolor,exception);
            break;
          }
        if (LocaleCompare("translate",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
