      case 'v':
      case 'V':
      {
        if (LocaleCompare("viewbox",keyword) == 0)
          {
            GetNextToken(q,&q,extent,primitive_token);
            graphic_context[n]->viewbox.x=(ssize_t) ceil(StringToDouble(primitive_token,
